SRT = r"D:\TLP\KỊCH BẢN\KBP-002.srt"
def sec(x):
    h,m,r=x.split(":"); s,ms=r.split(","); return int(h)*3600+int(m)*60+int(s)+int(ms)/1000
def hhmmss(v):
    v=round(v); return f"{v//3600:02d}:{(v%3600)//60:02d}:{v%60:02d}"
E={}; n=0
for b in re.split(r"\n\s*\n", open(SRT, encoding="utf-8-sig").read().strip()):
    L=[l for l in b.splitlines() if l.strip()]
    if len(L)<2: continue
    a,bb=L[1].split(" --> "); n+=1; E[n]=(sec(a),sec(bb))

# ---- locked character + style (illustration only, anti-photoreal) ----
CHAR = ("the SAME recurring heroine, identical in every scene: a comic/watercolor-illustrated "
        "woman in her late 30s with a friendly oval face, brown hair pulled back in a low "
        "ponytail with soft side-parted bangs, small teal-green stud earrings, a thin necklace, "
        "a green-and-purple horizontally striped short-sleeve scoop-neck t-shirt, light-blue "
        "high-waisted jeans cuffed at the ankles, and green canvas lace-up sneakers with white "
        "soles, warm calm expression")
STYLE = ("clean comic line-art with soft watercolor coloring, warm natural palette, gentle "
         "cel-style shading, with occasional subtle colorful watercolor paint-splatter accents "
         "(purple, blue, pink, yellow); stylized 2D illustrated characters only — never "
         "photorealistic, no real-person photography; absolutely NO text, letters, words or "
         "numbers anywhere in the frame")
ANIM  = ("2D HAND-DRAWN CARTOON ANIMATION, flat cel-shaded comic illustration with clean ink "
         "outlines and soft watercolor coloring (animated drawing, in the style of an illustrated "
         "storybook / motion-comic)")
NOREAL = ("IMPORTANT STYLE LOCK: everything is a drawn animated cartoon — NOT live action, NOT "
          "photorealistic, NOT 3D CGI, NOT a real human being; the character and all supporting "
          "figures are flat hand-drawn illustrations with visible ink linework and watercolor "
          "shading. No real people, no photographic faces, no text or letters anywhere")
def img(scene, cam):
    return (f"{ANIM}. {scene} The heroine is {CHAR}, kept clearly the central focus, drawn in flat "
            f"cartoon illustration. Supporting figures and props are drawn in the exact same "
            f"hand-drawn cartoon style. {STYLE}. {cam}. {NOREAL}.")

