wb=openpyxl.Workbook(); ws=wb.active; ws.title="Storyboard KBP-002"
headers=["STT","Timecode (bắt đầu - kết thúc)","Thời lượng (giây)","Nội dung gốc (FR)",
         "Bản dịch tiếng Việt","Image Prompt (EN) - NO TEXT","Video Prompt (EN) - NO TEXT","Ghi chú"]
hf=PatternFill("solid",fgColor="2F5496"); hfont=Font(bold=True,color="FFFFFF",size=11)
thin=Side(style="thin",color="BFBFBF"); bd=Border(left=thin,right=thin,top=thin,bottom=thin)
wrap=Alignment(wrap_text=True,vertical="top"); ctr=Alignment("center","center",wrap_text=True)
ws.append(headers)
for c in range(1,len(headers)+1):
    cc=ws.cell(1,c); cc.fill=hf; cc.font=hfont; cc.alignment=ctr; cc.border=bd
seen=set(); vseen=set(); issues=[]
for i,(a,b,fr,vi,scene,video,note) in enumerate(S,1):
    start=E[a][0]; end=E[b][1]; dur=round(end-start,1)
    if not (5.0<=dur<=10.05): issues.append((i,dur))
    image=img(scene,"medium shot, eye-level" if i%3 else "medium-wide, soft depth")
    video_full=(f"{ANIM}. Keep the SAME drawn cartoon character unchanged (only her expression and "
                f"movement change), smooth hand-drawn 2D animation. {video} {NOREAL}.")
    assert image not in seen and video_full not in vseen, f"DUP {i}"
    seen.add(image); vseen.add(video_full)
    ws.append([i, f"{hhmmss(start)} - {hhmmss(end)}", dur, fr, vi, image, video_full, note]); r=ws.max_row
    for c in range(1,len(headers)+1):
        cell=ws.cell(r,c); cell.border=bd; cell.alignment=ctr if c in (1,2,3) else wrap
    if i%2==0:
        for c in range(1,len(headers)+1): ws.cell(r,c).fill=PatternFill("solid",fgColor="EEF1F8")
for col,w in {"A":6,"B":24,"C":12,"D":44,"E":44,"F":76,"G":62,"H":34}.items():
    ws.column_dimensions[col].width=w
ws.freeze_panes="A2"; ws.row_dimensions[1].height=32
out=r"D:\TLP\KỊCH BẢN\KBP-002_storyboard.xlsx"; wb.save(out)
print("OK scenes:",len(S),"| dur issues:",issues,"| uniq img:",len(seen),"| uniq vid:",len(vseen),
      "| span", round(E[S[0][0]][0],1),"->",round(E[S[-1][1]][1],1))
